            charset.push(c);
        }
    }

    if charset.is_empty() {
        return Err(CliArgumentError {
            message: "Custom charset definition is empty".to_string(),
        });
    }

    // deduplicate while preserving order
    let mut seen = Vec::with_capacity(charset.len());
    for c in charset {
        if !seen.contains(&c) {
            seen.push(c);
        }
    }

    Ok(seen)
}

